{
  "steps": [
    {
      "step_id": 1,
      "time": "07:55",
      "role": "企业中控室值班员",
      "action": "先期处置",
      "description": "中控室值班员通过可燃有毒气体报警系统发现储罐区T-102苯储罐区域浓度异常升高，立即通知当班巡检人员佩戴便携式检测仪前往现场核查，同时启动罐区固定喷淋系统进行预处置，并持续盯守DCS画面。",
      "resources": [
        {"resource_type": "便携式气体检测仪", "quantity": 2}
      ]
    },
    {
      "step_id": 2,
      "time": "07:58",
      "role": "企业当班巡检员",
      "action": "现场侦检",
      "description": "当班巡检员到达储罐区外围，使用便携式检测仪确认苯蒸气浓度超标，发现T-102储罐底部法兰处有液体持续泄漏并形成液池，伴有刺激性气味扩散，立即向中控室报告泄漏位置、介质和扩散方向。",
      "resources": [
        {"resource_type": "便携式气体检测仪", "quantity": 1},
        {"resource_type": "防化装备", "quantity": 2}
      ]
    },
    {
      "step_id": 3,
      "time": "08:00",
      "role": "企业应急指挥部",
      "action": "启动响应",
      "description": "企业应急指挥部接报后立即启动《危险化学品泄漏事故应急预案》一级响应，成立现场应急指挥部，由企业总经理任总指挥，通知各应急小组集结，同时向属地应急管理局、生态环境局和消防救援机构报告事故情况。",
      "resources": [
        {"resource_type": "卫星电话", "quantity": 1}
      ]
    },
    {
      "step_id": 4,
      "time": "08:03",
      "role": "企业应急处置组",
      "action": "泄漏控制",
      "description": "应急处置组佩戴正压式空气呼吸器和防化服进入罐区，尝试关闭T-102储罐底部法兰上游阀门，切断泄漏源；同时利用围油栏和沙袋在泄漏液池外围构筑围堰，防止泄漏液体流入雨水管网和周边水体。",
      "resources": [
        {"resource_type": "防化装备", "quantity": 6},
        {"resource_type": "围油栏", "quantity": 4},
        {"resource_type": "沙袋", "quantity": 50}
      ]
    },
    {
      "step_id": 5,
      "time": "08:05",
      "role": "企业疏散引导组",
      "action": "人员疏散",
      "description": "疏散引导组按照预案设定的疏散路线，组织储罐区周边办公区、化验室及维修车间人员向上风向安全集合点撤离，逐人清点并登记，确保无人员滞留。",
      "resources": [
        {"resource_type": "扩音器", "quantity": 2},
        {"resource_type": "对讲机", "quantity": 4}
      ]
    },
    {
      "step_id": 6,
      "time": "08:06",
      "role": "企业警戒保卫组",
      "action": "危险区划定",
      "description": "警戒保卫组根据泄漏物质特性和气象条件，初步划定热区、温区和冷区，在罐区周边设置警戒带和警示标志，禁止无关人员和车辆进入，并在厂区大门设置引导点。",
      "resources": [
        {"resource_type": "警戒带", "quantity": 10},
        {"resource_type": "警示标志", "quantity": 8},
        {"resource_type": "对讲机", "quantity": 2}
      ]
    },
    {
      "step_id": 7,
      "time": "08:08",
      "role": "企业医疗救护组",
      "action": "救护设点",
      "description": "医疗救护组在上风向冷区设立临时医疗救护点，配备急救包和解毒药品，做好接诊可能中毒人员的准备，并安排救护车在厂区外待命。",
      "resources": [
        {"resource_type": "急救包", "quantity": 3},
        {"resource_type": "救护车", "quantity": 1},
        {"resource_type": "帐篷", "quantity": 1}
      ]
    },
    {
      "step_id": 8,
      "time": "08:10",
      "role": "企业应急指挥部",
      "action": "事故上报",
      "description": "企业应急指挥部向属地应急管理局、生态环境局、消防救援大队和属地街道办事处书面报告事故基本情况，包括泄漏介质、泄漏量、影响范围和已采取的先期处置措施，并请求外部救援力量增援。",
      "resources": [
        {"resource_type": "卫星电话", "quantity": 1},
        {"resource_type": "传真机", "quantity": 1}
      ]
    },
    {
      "step_id": 9,
      "time": "08:12",
      "role": "属地应急管理局",
      "action": "启动响应",
      "description": "属地应急管理局接报后启动危险化学品事故应急响应，成立现场指挥部，由局主要负责人任现场总指挥，通知公安、生态环境、卫健、消防等部门赶赴现场，统一协调指挥各救援力量。",
      "resources": [
        {"resource_type": "应急指挥车", "quantity": 1}
      ]
    },
    {
      "step_id": 10,
      "time": "08:15",
      "role": "消防救援大队",
      "action": "消防灭火",
      "description": "消防救援大队到达现场后，根据现场侦检情况，出设泡沫水枪对泄漏液池进行覆盖，抑制苯蒸气挥发，同时对邻近储罐进行冷却保护，防止火源引燃和事故扩大。",
      "resources": [
        {"resource_type": "消防车", "quantity": 3},
        {"resource_type": "泡沫液", "quantity": 2},
        {"resource_type": "防化装备", "quantity": 8}
      ]
    },
    {
      "step_id": 11,
      "time": "08:18",
      "role": "属地公安局",
      "action": "交通管制",
      "description": "属地公安局在事故现场周边主要路口设置交通管制点，对厂区周边道路实施临时封闭，疏导过往车辆绕行，保障应急救援车辆和人员通行顺畅。",
      "resources": [
        {"resource_type": "警车", "quantity": 2},
        {"resource_type": "警戒带", "quantity": 6},
        {"resource_type": "交通标志牌", "quantity": 4}
      ]
    },
    {
      "step_id": 12,
      "time": "08:20",
      "role": "属地生态环境局",
      "action": "环境监测",
      "description": "属地生态环境局监测人员在下风向厂界外设置多个大气监测点和废水监测点，使用环境监测设备对苯蒸气浓度和周边水体进行连续监测，及时向现场指挥部报告监测数据。",
      "resources": [
        {"resource_type": "环境监测设备", "quantity": 4},
        {"resource_type": "无人机", "quantity": 1}
      ]
    },
    {
      "step_id": 13,
      "time": "08:22",
      "role": "属地卫健委",
      "action": "医疗救护",
      "description": "属地卫健委组织急救力量到达现场，在临时医疗救护点对可能接触泄漏化学品的员工进行检伤分类和初步诊治，对一名出现头晕恶心症状的员工进行现场急救并安排救护车转运至医院。",
      "resources": [
        {"resource_type": "救护车", "quantity": 2},
        {"resource_type": "急救包", "quantity": 5}
      ]
    },
    {
      "step_id": 14,
      "time": "08:25",
      "role": "企业应急处置组",
      "action": "污染源切断",
      "description": "企业应急处置组在消防掩护下成功关闭T-102储罐底部法兰上游阀门，泄漏源被切断；随后使用防爆泵将围堰内泄漏液体转移至应急事故池，防止污染扩大。",
      "resources": [
        {"resource_type": "防爆泵", "quantity": 2},
        {"resource_type": "运输车辆", "quantity": 1},
        {"resource_type": "防化装备", "quantity": 4}
      ]
    },
    {
      "step_id": 15,
      "time": "08:30",
      "role": "企业洗消组",
      "action": "洗消作业",
      "description": "企业洗消组在温区设置洗消通道，对從热区撤出的救援人员和被污染的装备进行洗消，洗消废水统一收集至应急事故池，防止二次污染。",
      "resources": [
        {"resource_type": "洗消药剂", "quantity": 10},
        {"resource_type": "帐篷", "quantity": 2},
        {"resource_type": "防化装备", "quantity": 4}
      ]
    },
    {
      "step_id": 16,
      "time": "08:35",
      "role": "现场指挥部",
      "action": "统一指挥",
      "description": "现场指挥部召开第一次现场会商会，听取企业、消防、生态环境、卫健等部门情况汇报，研判泄漏处置进展和环境影响趋势，部署下一步泄漏物收集、环境监测和人员安置等工作。",
      "resources": [
        {"resource_type": "应急指挥车", "quantity": 1},
        {"resource_type": "卫星电话", "quantity": 1},
        {"resource_type": "发电机", "quantity": 1}
      ]
    },
    {
      "step_id": 17,
      "time": "08:40",
      "role": "属地街道办事处",
      "action": "周边疏散",
      "description": "属地街道办事处根据现场指挥部指令，组织厂区周边500米范围内居民进行有序疏散，引导居民前往临时安置点，并做好人员登记和情绪安抚工作。",
      "resources": [
        {"resource_type": "运输车辆", "quantity": 4},
        {"resource_type": "扩音器", "quantity": 3},
        {"resource_type": "帐篷", "quantity": 5}
      ]
    },
    {
      "step_id": 18,
      "time": "08:45",
      "role": "属地民政局",
      "action": "安置救助",
      "description": "属地民政局在临时安置点设置救助服务站，为疏散居民提供饮用水、食品、毛毯等基本生活物资，并安排工作人员做好登记和安抚工作。",
      "resources": [
        {"resource_type": "帐篷", "quantity": 5},
        {"resource_type": "饮用水", "quantity": 50},
        {"resource_type": "食品", "quantity": 100},
        {"resource_type": "毛毯", "quantity": 50}
      ]
    },
    {
      "step_id": 19,
      "time": "08:50",
      "role": "企业应急指挥部",
      "action": "信息通报",
      "description": "企业应急指挥部通过厂区广播和短信平台向全体员工通报事故处置进展，告知泄漏源已切断、环境监测持续达标，要求员工保持冷静、服从指挥，不传谣不信谣。",
      "resources": [
        {"resource_type": "广播系统", "quantity": 1},
        {"resource_type": "短信平台", "quantity": 1}
      ]
    },
    {
      "step_id": 20,
      "time": "08:55",
      "role": "属地宣传部",
      "action": "宣传引导",
      "description": "属地宣传部通过官方微博、微信公众号等渠道发布事故信息通报，说明事故基本情况、已采取的措施和周边环境监测结果，回应社会关切，引导舆论客观理性。",
      "resources": [
        {"resource_type": "计算机", "quantity": 2},
        {"resource_type": "照相机", "quantity": 1}
      ]
    },
    {
      "step_id": 21,
      "time": "09:00",
      "role": "属地生态环境局",
      "action": "污染评估",
      "description": "属地生态环境局根据连续监测数据，对事故周边大气、水体和土壤环境进行污染评估，编制环境监测报告，评估事故对周边环境的影响程度和范围。",
      "resources": [
        {"resource_type": "环境监测设备", "quantity": 4},
        {"resource_type": "无人机", "quantity": 1},
        {"resource_type": "计算机", "quantity": 2}
      ]
    },
    {
      "step_id": 22,
      "time": "09:10",
      "role": "企业应急处置组",
      "action": "危害消除",
      "description": "企业应急处置组使用吸附材料和中和药剂对罐区地面残留泄漏物进行彻底清理，清理产生的危险废物统一收集、分类贮存，交由有资质单位处置。",
      "resources": [
        {"resource_type": "吸附材料", "quantity": 20},
        {"resource_type": "中和药剂", "quantity": 10},
        {"resource_type": "运输车辆", "quantity": 2},
        {"resource_type": "防化装备", "quantity": 6}
      ]
    },
    {
      "step_id": 23,
      "time": "09:20",
      "role": "企业设备抢修组",
      "action": "设施抢修",
      "description": "企业设备抢修组对T-102储罐泄漏法兰进行更换和紧固，对罐区相关管道、阀门和仪表进行全面检查维修，确保设备设施恢复正常安全状态。",
      "resources": [
        {"resource_type": "维修工具", "quantity": 4},
        {"resource_type": "备用法兰", "quantity": 2},
        {"resource_type": "防化装备", "quantity": 4}
      ]
    },
    {
      "step_id": 24,
      "time": "09:30",
      "role": "属地生态环境局",
      "action": "环境合格",
      "description": "属地生态环境局对事故现场及周边大气、水体进行最终监测，确认苯蒸气浓度和废水指标均已降至安全限值以下，环境质量恢复正常，出具环境达标确认意见。",
      "resources": [
        {"resource_type": "环境监测设备", "quantity": 4}
      ]
    },
    {
      "step_id": 25,
      "time": "09:35",
      "role": "现场指挥部",
      "action": "撤除警戒",
      "description": "现场指挥部根据环境监测达标确认和现场处置完成情况，下令撤除事故现场警戒，恢复厂区周边道路交通，组织疏散居民有序返回。",
      "resources": [
        {"resource_type": "对讲机", "quantity": 4},
        {"resource_type": "扩音器", "quantity": 2}
      ]
    },
    {
      "step_id": 26,
      "time": "09:40",
      "role": "现场指挥部",
      "action": "响应终止",
      "description": "现场指挥部确认泄漏源已切断、泄漏物已清理、环境监测达标、人员全部撤离和安置妥当，宣布终止应急响应，转入后期处置和事故调查阶段。",
      "resources": [
        {"resource_type": "卫星电话", "quantity": 1}
      ]
    },
    {
      "step_id": 27,
      "time": "09:50",
      "role": "企业应急指挥部",
      "action": "善后处置",
      "description": "企业应急指挥部组织开展善后处置工作，包括受伤人员救治和抚恤、周边居民安置补偿、事故现场清理和生态恢复，配合政府部门开展事故调查。",
      "resources": [
        {"resource_type": "计算机", "quantity": 2},
        {"resource_type": "运输车辆", "quantity": 2}
      ]
    },
    {
      "step_id": 28,
      "time": "10:00",
      "role": "现场指挥部",
      "action": "总结评估",
      "description": "现场指挥部组织参演单位和专家召开演练总结评估会，对预警报警、应急响应、指挥协调、现场处置、环境监测、人员疏散等环节进行复盘评估，总结经验教训，提出预案修订和应急能力提升建议。",
      "resources": [
        {"resource_type": "投影仪", "quantity": 1},
        {"resource_type": "计算机", "quantity": 3}
      ]
    }
  ]
}
